use serde::{Deserialize,Serialize}; use super::{decision::Decision,error::{AdmissionError,AdmissionErrorKind,Result},subject::SubjectId};
#[derive(Clone,Debug,Serialize,Deserialize,PartialEq,Eq)] pub enum TxState{Open,Prepared,Committed,Aborted}
#[derive(Clone,Debug,Serialize,Deserialize)] pub struct AdmissionTx{pub id:String,pub subjects:Vec<SubjectId>,pub decisions:Vec<Decision>,pub state:TxState,pub epoch:u64}
impl AdmissionTx{pub fn new(id:impl Into<String>,epoch:u64)->Self{Self{id:id.into(),subjects:vec![],decisions:vec![],state:TxState::Open,epoch}}pub fn stage(&mut self,s:SubjectId,d:Decision)->Result<()>{if self.state!=TxState::Open{return Err(AdmissionError::new(AdmissionErrorKind::Conflict,"tx.not_open","cannot stage outside open transaction"))}s.validate()?;self.subjects.push(s);self.decisions.push(d);Ok(())}pub fn prepare(&mut self)->Result<()>{if self.state!=TxState::Open||self.subjects.is_empty(){return Err(AdmissionError::new(AdmissionErrorKind::Conflict,"tx.prepare.invalid","open non-empty transaction required"))}if self.decisions.iter().any(|d|matches!(d,Decision::Refuse{..})){self.state=TxState::Aborted;return Err(AdmissionError::new(AdmissionErrorKind::Conflict,"tx.refused","refused member aborts atomic batch"))}self.state=TxState::Prepared;Ok(())}pub fn commit(&mut self)->Result<()>{if self.state!=TxState::Prepared{return Err(AdmissionError::new(AdmissionErrorKind::Conflict,"tx.not_prepared","prepare before commit"))}self.state=TxState::Committed;Ok(())}pub fn abort(&mut self){if self.state!=TxState::Committed{self.state=TxState::Aborted}}}